std::string decoded;
std::shared_ptr<Node> current = root;
int bits_processed = 0;
char byte = 0;
int bits_remaining_in_byte = 0;

while (bits_processed < encoded_length) {
    if (bits_remaining_in_byte == 0) {
        if (!infile.read(&byte, 1)) {
            break; // no more data
        }
        bits_remaining_in_byte = 8;
    }

    // Extract the most‑significant bit
    int bit = (static_cast<unsigned char>(byte) >> 7) & 1;
    // Shift left to bring the next bit to the MSB position
    byte = static_cast<char>(static_cast<unsigned char>(byte) << 1);
    --bits_remaining_in_byte;

    // Traverse the Huffman tree
    if (bit == 0) {
        current = current->left;
    } else {
        current = current->right;
    }

    // If we reached a leaf node, output the character and reset to root
    if (!current->left && !current->right) {
        decoded.push_back(static_cast<char>(current->character));
        current = root;
    }

    ++bits_processed;
}

return decoded;

